MISSING_FIELDS_MARKUP = '''<dialog id="missing-fields-dialog" class="missing-fields-dialog" aria-labelledby="missing-fields-title"><div class="missing-fields-body"><p class="kicker">CÙNG INTAKE · GIỮ NGUYÊN ẢNH VÀ NGUỒN</p><h2 id="missing-fields-title">Bổ sung thông tin còn thiếu</h2><div id="missing-fields-record" class="missing-fields-record"></div><div id="missing-fields-known" class="missing-fields-known"></div><form id="missing-fields-form"><div id="missing-fields-inputs" class="missing-fields-grid"></div><p id="missing-fields-status" class="missing-fields-help" role="status"></p><div class="missing-fields-actions"><button id="missing-fields-save" type="button" class="secondary">Lưu nháp</button><button id="missing-fields-continue" type="submit">BỔ SUNG & TIẾP TỤC TẠO CONTENT</button><button id="missing-fields-close" type="button" class="secondary">Đóng</button></div></form></div></dialog><nav class="home-bottom-nav" aria-label="Điều hướng nhanh"><a href="#home-dashboard"><b>⌂</b>Home</a><a href="#intake-section"><b>＋</b>Nguồn</a><a href="#review-section"><b>▤</b>Content</a><a href="/website"><b>⌂</b>Website</a><a href="#queue-section"><b>•••</b>Khác</a></nav>'''

HOME_SCRIPT = r'''<script>
(()=>{'use strict';const dialog=document.querySelector('#missing-fields-dialog'),inputs=document.querySelector('#missing-fields-inputs'),form=document.querySelector('#missing-fields-form'),status=document.querySelector('#missing-fields-status');let activeId=null,activeRevision=1;
const meta={title:['Tên bất động sản','text'],address:['Địa chỉ / vị trí','text'],area:['Diện tích','text'],property_type:['Loại bất động sản','select',['APARTMENT','HOUSE','LAND']],transaction_type:['Giao dịch','select',['SALE','RENT']],price_vnd:['Giá bán (VND)','number'],price_vnd_per_month:['Giá thuê mỗi tháng (VND)','number'],price_cycle:['Chu kỳ giá thuê','select',['MONTH']],house_type:['Loại nhà','text'],bedrooms:['Số phòng ngủ','number'],bathrooms:['Số phòng tắm','number']};
function node(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el}
function addFactInput(key,value){const spec=meta[key],wrap=node('label','',spec?.[0]||key),type=spec?.[1]||'text';let input;if(type==='select'){input=node('select');const empty=node('option','','Chọn…');empty.value='';input.append(empty);for(const option of spec[2]){const o=node('option','',option);o.value=option;input.append(o)}}else{input=node('input');input.type=type;if(type==='number'){input.min='0';input.step='any'}}input.name=key;input.required=true;input.value=value==null?'':String(value);wrap.append(input);inputs.append(wrap)}
function openMissing(id,result,record){activeId=id;activeRevision=Number(record?.inputRevision||result.input_revision||1);const evidence=record?.ownerEvidence||{},known=record?.preliminaryFacts||{};document.querySelector('#missing-fields-record').textContent=id+' · '+(record?.source||'Nguồn đã lưu')+' · '+(record?.media||[]).length+' media · '+(record?.note||'Không có ghi chú nguồn');const knownLines=Object.entries(known).filter(([k,v])=>v!==''&&v!=null).map(([k,v])=>(meta[k]?.[0]||k)+': '+String(v));document.querySelector('#missing-fields-known').textContent='Thông tin đã có: '+(knownLines.join(' · ')||'Chưa trích xuất được trường có cấu trúc')+'. Tệp gốc vẫn được giữ trong Intake.';inputs.replaceChildren();for(const key of result.missing_fields||[])addFactInput(key,known[key]);const evidenceMissing=new Set(result.missing_evidence||[]);for(const key of evidenceMissing){const label={source_id:'Mã nguồn trích dẫn',claim:'Thông tin nguồn xác nhận',rights_status:'Quyền sử dụng nguồn'}[key]||key,wrap=node('label','',label);let input;if(key==='rights_status'){input=node('select');for(const [v,t] of [['','Chọn quyền…'],['PERSONAL','Cá nhân'],['COMPANY','Công ty'],['APPROVED','Đã có chấp thuận']]){const o=node('option','',t);o.value=v;input.append(o)}}else{input=node(key==='claim'?'textarea':'input');input.maxLength=key==='claim'?1200:160}input.name='evidence_'+key;input.required=true;input.value=evidence[key]||'';wrap.append(input);inputs.append(wrap)}status.textContent='Chưa gọi AI. Máy chủ sẽ kiểm tra lại đúng Intake trước khi tiếp tục.';if(!dialog.open)dialog.showModal()}
window.openMissingFields=openMissing;document.querySelector('#missing-fields-close').onclick=()=>dialog.close();
const preflightButton=document.querySelector('[data-home-ai-preflight]'),preflightResult=document.querySelector('[data-home-ai-preflight-result]');preflightButton.onclick=async()=>{preflightButton.disabled=true;preflightResult.textContent='Đang kiểm tra trong Admin staging…';try{const response=await fetch('/api/admin/credential-preflight',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:'{}'}),result=await response.json();preflightResult.textContent=result.status+(result.error?' · '+result.error:'')+(result.os_status!=null?' · OSStatus '+result.os_status:'')+' · request_sent='+String(result.request_sent===true);document.querySelector('[data-home-ai]').textContent=result.status==='READY'?'Sẵn sàng':'Chưa sẵn sàng'}catch(_){preflightResult.textContent='Không nhận được trạng thái kiểm tra.'}finally{preflightButton.disabled=false}};
async function saveDraft(){if(!activeId)return false;const record=(window.intakeRecords||[]).find(x=>x.id===activeId)||{},facts={},evidence={...(record.ownerEvidence||{})};for(const el of inputs.querySelectorAll('[name]')){if(el.name.startsWith('evidence_'))evidence[el.name.slice(9)]=el.value.trim();else facts[el.name]=el.type==='number'&&el.value!==''?Number(el.value):el.value.trim()}status.textContent='Đang lưu nháp đúng Intake…';const response=await fetch('/api/intakes/'+encodeURIComponent(activeId)+'/draft',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({expected_input_revision:activeRevision,facts,evidence})});let data;try{data=await response.json()}catch(_){status.textContent='Phản hồi lưu nháp không hợp lệ.';return false}if(!response.ok){status.textContent=data.error==='STALE_INTAKE_REVISION'?'Intake vừa được cập nhật. Tải lại Queue rồi mở lại hồ sơ.':(data.error||'Không lưu được nháp.');return false}activeRevision=Number(data.input_revision||activeRevision+1);const updated={...record,inputRevision:activeRevision,preliminaryFacts:{...(record.preliminaryFacts||{}),...facts},ownerEvidence:evidence};window.intakeRecords=(window.intakeRecords||[]).map(x=>x.id===activeId?updated:x);status.textContent='Đã lưu nháp · '+activeId+' · ảnh/tệp gốc không thay đổi.';return true}
document.querySelector('#missing-fields-save').onclick=()=>{saveDraft().catch(()=>status.textContent='Không lưu được nháp.')};form.addEventListener('submit',async e=>{e.preventDefault();const button=document.querySelector('#missing-fields-continue');button.disabled=true;try{if(!await saveDraft())return;const id=activeId;if(await createContent(id,button)){dialog.close();if(pendingSavedIntakeId===id){intakeForm.reset();pendingSavedIntakeId=null;intakeFiles.forEach(x=>{if(x.url)URL.revokeObjectURL(x.url)});intakeFiles=[];renderIntakeFiles();document.querySelector('#intake-new').hidden=true}}}catch(_){status.textContent='Không thể tiếp tục; Intake đã lưu vẫn còn trong Queue.'}finally{button.disabled=false}});
function testOnly(x){return x.source==='TEST_ONLY'||[x.sourceGroup,x.note,x.clientBatchId].some(v=>String(v||'').includes('TEST_ONLY'))}
Promise.allSettled([fetch('/api/admin/status',{credentials:'same-origin',cache:'no-store'}).then(r=>r.json()),fetch('/api/intakes',{credentials:'same-origin',cache:'no-store'}).then(r=>r.json()),fetch('/api/reviews',{credentials:'same-origin',cache:'no-store'}).then(r=>r.json()),fetch('/api/errors',{credentials:'same-origin',cache:'no-store'}).then(r=>r.json())]).then(rs=>{const get=i=>rs[i].status==='fulfilled'?rs[i].value:null,ai=get(0),items=get(1),reviews=get(2),errors=get(3),rows=Array.isArray(items)?items:[],real=rows.filter(x=>!testOnly(x)),reviewRows=Array.isArray(reviews)?reviews:[],queued=real.filter(x=>['RECEIVED','DRAFT_NEEDS_REVIEW'].includes(x.status||'RECEIVED')).length;document.querySelector('[data-home-ai]').textContent=ai?.content_live_enabled?'Sẵn sàng':'Chưa sẵn sàng';document.querySelector('[data-home-web]').textContent=ai?.website_state==='CONNECTED_E2E'?'E2E PASS':'Chưa E2E';document.querySelector('[data-home-queue]').textContent=String(queued);document.querySelector('[data-home-intakes]').textContent=String(queued);document.querySelector('[data-home-content]').textContent=String(reviewRows.filter(x=>!['APPROVED','REJECTED'].includes(x.state)).length);document.querySelector('[data-home-pending-web]').textContent=String(reviewRows.filter(x=>x.state==='APPROVED'&&!['PUBLISHED','PUBLIC_ALLOWED'].includes(x.publication_state||'')).length);document.querySelector('[data-home-published]').textContent=String(reviewRows.filter(x=>['PUBLISHED','PUBLIC_ALLOWED'].includes(x.publication_state||'')).length);document.querySelector('[data-home-summary-intakes]').textContent=String(real.length);document.querySelector('[data-home-summary-reviews]').textContent=String(reviewRows.length);document.querySelector('[data-home-summary-public]').textContent=document.querySelector('[data-home-published]').textContent;document.querySelector('[data-home-summary-errors]').textContent=String(Array.isArray(errors)?errors.filter(x=>x.status!=='succeeded').length:0);const work=document.querySelector('[data-home-work]');work.replaceChildren();for(const row of real.slice(0,4)){const item=node('div','home-work-row'),title=node('b','',row.id+' · '+(row.status||'RECEIVED')),detail=node('small','',(row.media||[]).length+' media · '+(row.note||'Nguồn đã lưu')),link=node('a','','Mở hàng đợi xử lý');link.href='#queue-section';item.append(title,detail,link);work.append(item)}if(!real.length)work.textContent='Chưa có nguồn cần xử lý.';if(rows.length>real.length){const hidden=node('p','missing-fields-help',rows.length-real.length+' intake TEST_ONLY được ẩn khỏi hàng đợi vận hành; dữ liệu chưa bị xóa.');work.append(hidden)}window.intakeRecords=rows});
})();
</script>'''
